/* IdMap -- an append-only, id-keyed map.

   Three differences from z_Map.c.tmpl, all of them consequences of "no
   removal" and "the key is an unsigned scalar":

     * No `alive` byte and no stored `hash`. Nothing is ever removed, so
       `entries[0 .. length-1]` are ALL live -- the array is dense with no
       holes. That collapses Map's `length` / `entries_len` pair into one
       counter, which is simultaneously the live count, the used-slot count
       and the next insertion index.
     * `indices` is uint32_t holding `pos + 1`, with 0 for empty. There is no
       DELETED sentinel, so `find` has no tombstone branch, `set` has no
       first-deleted scan and `grow` has no compaction pass.
     * The struct is returned BY VALUE and `destroy` does not free it: this is
       a stack struct like z_List, not a heap object like z_Map. An empty one
       costs no allocation at all.

   `entries` is sized at capacity*2/3 -- the same 2/3 load factor the index
   grows at -- so "entries is full" and "the index must grow" are one event,
   and no separate entries_cap field is needed. The growth test itself carries
   no division: cross-multiplied it is (length+1)*3 >= capacity*2. */

/* Below this index size no `indices` array is allocated and `find` scans the
   dense entries instead; `indices == NULL` is the discriminator, so the large
   path pays no extra branch. Capacity 16 admits 10 entries, which covers ~90%
   of the containers a self-compile creates. This file is read from disk at
   emit time, so changing the constant needs no compiler rebuild. */
#define Z_T1607_SMALL_MAX 16

typedef struct {
    uint64_t key;
    z_t1552_t value;
} z_t1607_entry_t;

typedef struct z_t1607_t {
    uint32_t length;
    uint32_t capacity;
    uint32_t* indices;
    z_t1607_entry_t* entries;
} z_t1607_t;

/* THE INDEX FUNCTION -- the one knob. Identity (`(uint64_t)_key`) is optimal
   for a dense run of ids and pathological for a sparse subset of a wide id
   space, where `& mask` folds unrelated groups onto each other: measured over
   a self-compile it cost +77% probe steps and took the worst run from 74 to
   749. The golden-ratio multiply costs one imul plus one shift and beat the
   splitmix64 finalizer it replaces on both total steps and tail. The shift is
   not optional: bit i of a product depends only on bits 0..i of the operands,
   so a multiply's low bits -- exactly the ones `& (capacity-1)` reads -- are
   barely mixed, while the high half carries every input bit. */
static uint64_t z_t1607_slot(uint64_t _key);
static uint64_t z_t1607_slot(uint64_t _key) {
    return (((uint64_t)_key) * 0x9E3779B97F4A7C15ULL) >> 32;
}

/* how many entries an index of this size admits, at the 2/3 load factor */
static uint32_t z_t1607_entries_cap(uint32_t _capacity);
static uint32_t z_t1607_entries_cap(uint32_t _capacity) {
    return (uint32_t)((((uint64_t)_capacity) * 2u) / 3u);
}

static void z_t1607_destroy(z_t1607_t* p);
static void z_t1607_destroy(z_t1607_t* p) {
    if (!p) return;
    for (uint32_t i = 0; i < p->length; i++) {
        z_t1552_destroy(&p->entries[i].value);
    }
    free(p->indices);
    free(p->entries);
    /* NO free(p) -- the struct is on the stack */
}

static z_t1607_t z_t1607_create(uint64_t _capacity);
static z_t1607_t z_t1607_create(uint64_t _capacity) {
    z_t1607_t _this = {0};
    if (_capacity > 0) {
        uint32_t _p2 = 8;
        while ((uint64_t)z_t1607_entries_cap(_p2) < _capacity && _p2 < 0x40000000u) {
            _p2 <<= 1;
        }
        _this.capacity = _p2;
        _this.entries = (z_t1607_entry_t*)z_xcalloc(
            z_t1607_entries_cap(_p2), sizeof(z_t1607_entry_t));
        if (_p2 > Z_T1607_SMALL_MAX) {
            _this.indices = (uint32_t*)z_xcalloc(_p2, sizeof(uint32_t));
        }
    }
    return _this;
}

/* Double the index and re-slot. `entries` is dense and stays in insertion
   order, so there is nothing to compact -- only the sparse index is rebuilt,
   and only once it is worth having. */
static void z_t1607_grow(z_t1607_t* _this);
static void z_t1607_grow(z_t1607_t* _this) {
    uint32_t _new_cap = _this->capacity == 0 ? 8 : _this->capacity * 2;
    _this->entries = (z_t1607_entry_t*)z_xrealloc(_this->entries,
        (size_t)z_t1607_entries_cap(_new_cap) * sizeof(z_t1607_entry_t));
    _this->capacity = _new_cap;
    free(_this->indices);
    _this->indices = NULL;
    if (_new_cap > Z_T1607_SMALL_MAX) {
        _this->indices = (uint32_t*)z_xcalloc(_new_cap, sizeof(uint32_t));
        for (uint32_t i = 0; i < _this->length; i++) {
            uint64_t probe = z_t1607_slot(_this->entries[i].key) & (_new_cap - 1);
            while (_this->indices[probe]) probe = (probe + 1) & (_new_cap - 1);
            _this->indices[probe] = i + 1;
        }
    }
}

/* the entry index for `_key`, or -1. On a miss `_slot_out` (when given, and
   when an index exists) receives the index slot the key belongs in. */
static int64_t z_t1607_find(const z_t1607_t* _this, uint64_t _key, uint64_t* _slot_out);
static int64_t z_t1607_find(const z_t1607_t* _this, uint64_t _key, uint64_t* _slot_out) {
    if (!_this->indices) {
        for (uint32_t i = 0; i < _this->length; i++) {
            if (_this->entries[i].key == _key) return (int64_t)i;
        }
        return -1;
    }
    uint64_t _mask = _this->capacity - 1;
    uint64_t probe = z_t1607_slot(_key) & _mask;
    for (uint32_t i = 0; i < _this->capacity; i++) {
        uint32_t slot = _this->indices[probe];
        if (slot == 0) {
            if (_slot_out) *_slot_out = probe;
            return -1;
        }
        if (_this->entries[slot - 1].key == _key) {
            if (_slot_out) *_slot_out = probe;
            return (int64_t)(slot - 1);
        }
        probe = (probe + 1) & _mask;
    }
    return -1;
}

static void z_t1607_set(z_t1607_t* _this, uint64_t _key, z_t1552_t _val);
static void z_t1607_set(z_t1607_t* _this, uint64_t _key, z_t1552_t _val) {
    uint64_t _slot = 0;
    int64_t existing = z_t1607_find(_this, _key, &_slot);
    if (existing >= 0) {
        z_t1552_destroy(&_this->entries[existing].value);
        _this->entries[existing].value = _val;
        return;
    }
    if ((uint64_t)(_this->length + 1) * 3 >= (uint64_t)_this->capacity * 2) {
        z_t1607_grow(_this);
        /* the index was rebuilt (or has just appeared): re-probe for the slot */
        z_t1607_find(_this, _key, &_slot);
    }
    uint32_t pos = _this->length;
    _this->entries[pos].key = _key;
    _this->entries[pos].value = _val;
    _this->length++;
    if (_this->indices) _this->indices[_slot] = pos + 1;
}

/* A CONST receiver, as `find` already takes and as z_Set's `iterate` does:
   `get` reads, and declaring it `.view` in zerolang is what lets an IdMap be
   read through a readonly holder at all -- a heap Map escapes that question
   because its field read yields a pointer, a stack struct does not. The
   reference form casts the const away on the payload for the same reason
   iterate does: OptionView's data is a bare void* shared with the readers that
   hand out a mutable interior pointer, so const stops here. */
static z_t1610_t z_t1607_get(const z_t1607_t* _this, uint64_t _key);
static z_t1610_t z_t1607_get(const z_t1607_t* _this, uint64_t _key) {
    int64_t idx = z_t1607_find(_this, _key, NULL);
    z_t1610_t _r = {0};
    if (idx >= 0) {
        _r.tag = Z_T1610_TAG_1;
        _r.data = (void*)&_this->entries[idx].value;
    } else {
        _r.tag = Z_T1610_TAG_0;
        _r.data = NULL;
    }
    return _r;
}

static int z_t1607_has(const z_t1607_t* _this, uint64_t _key);
static int z_t1607_has(const z_t1607_t* _this, uint64_t _key) {
    return z_t1607_find(_this, _key, NULL) >= 0;
}

/* POSITIONAL reads. `entries` is dense and insertion-ordered, so position is a
   meaningful coordinate here in a way it is not in a Map, and reaching one
   costs an array index rather than a probe. They exist because an ordered walk
   whose body needs the container's owner cannot hold an iterator across it.
   `keyAt` answers a bare key -- the `idkey` bound makes it a scalar, and 0
   past the end is the same "no id" every id space already spells -- while
   `valueAt` answers `get`'s own return, since a value is not always a scalar
   and not always a copy. */
static uint64_t z_t1607_keyAt(const z_t1607_t* _this, uint64_t _i);
static uint64_t z_t1607_keyAt(const z_t1607_t* _this, uint64_t _i) {
    if (_i >= (uint64_t)_this->length) return (uint64_t)0;
    return _this->entries[_i].key;
}

static z_t1610_t z_t1607_valueAt(const z_t1607_t* _this, uint64_t _i);
static z_t1610_t z_t1607_valueAt(const z_t1607_t* _this, uint64_t _i) {
    int64_t idx = _i < (uint64_t)_this->length ? (int64_t)_i : -1;
    z_t1610_t _r = {0};
    if (idx >= 0) {
        _r.tag = Z_T1610_TAG_1;
        _r.data = (void*)&_this->entries[idx].value;
    } else {
        _r.tag = Z_T1610_TAG_0;
        _r.data = NULL;
    }
    return _r;
}

/* getMut hands back a pointer INTO the entry where the value family's `get`
   copies out, so an update writes the entry in place instead of going through
   `set`. One emitted function for both families: what differs is the declared
   return, exactly as ListRef.get (a view) and ListVal.get (a copy) already
   differ while sharing one getMut.

   Its own file, for the reason z_IdMapIter.c.tmpl is separate: a mono whose
   `getMut` never resolved must still emit its container, and a template read
   by a seed that cannot fill its holes writes them into the C verbatim. */

static z_t1610_t z_t1607_getMut(z_t1607_t* _this, uint64_t _key);
static z_t1610_t z_t1607_getMut(z_t1607_t* _this, uint64_t _key) {
    z_t1610_t _r = {0};
    int64_t idx = z_t1607_find(_this, _key, NULL);
    if (idx >= 0) {
        _r.tag = Z_T1610_TAG_1;
        _r.data = &_this->entries[idx].value;
    } else {
        _r.tag = Z_T1610_TAG_0;
        _r.data = NULL;
    }
    return _r;
}

/* The entry IS the projection: `entries` is dense, so a borrowed entry is a
   plain `&entries[idx]` and the cursor is an index test rather than a scan for
   the next live one. Insertion order, and nothing can perforate it. */
typedef z_t1607_entry_t z_t1623_t;

typedef struct {
    z_t1607_t* m;
    uint32_t idx;
} z_t1620_t;

static z_t1627_t z_t1620_call(z_t1620_t* _it);
static z_t1627_t z_t1620_call(z_t1620_t* _it) {
    z_t1627_t _out = {0};
    if (_it->idx < _it->m->length) {
        _out.tag = Z_T1627_TAG_1;
        _out.data = &_it->m->entries[_it->idx];
        _it->idx++;
        return _out;
    }
    _out.tag = Z_T1627_TAG_0;
    return _out;
}

static z_t1620_t z_t1607_iterateItems(const z_t1607_t* _this);
static z_t1620_t z_t1607_iterateItems(const z_t1607_t* _this) {
    z_t1620_t _it = {0};
    /* the same const stop as `get` and z_Set's `iterate`: OptionView's payload
       is a bare void*, so const cannot propagate into it */
    _it.m = (z_t1607_t*)_this;
    _it.idx = 0;
    return _it;
}

static uint64_t z_t1623_key(const z_t1623_t* _e);
static uint64_t z_t1623_key(const z_t1623_t* _e) {
    return _e->key;
}

static z_t1552_t z_t1623_value(const z_t1623_t* _e);
static z_t1552_t z_t1623_value(const z_t1623_t* _e) {
    return _e->value;
}

